static bool should_favor_valid_state(const libhtp_fuzzer::FuzzInput& input) {
    if (input.has_favor_valid_state()) return input.favor_valid_state();
    return env_int("PROTO_LIBERATOR_FAVOR_VALID_STATE", 0) != 0;
}

static inline void mark_api_direct_exec(size_t api_idx) {
    if (api_idx >= API_COUNT) return;
    g_api_seen[api_idx]++;
    g_api_executed[api_idx]++;
}

static void prime_valid_state_handles() {
    htp_cfg_t* cfg = (htp_cfg_t*)handle_get(8, 0, false, nullptr);
    if (cfg == nullptr) {
        cfg = htp_config_create();
        if (!cfg) return;
        handle_register(8, cfg);
    }

    bool created_connp = false;
    htp_connp_t* connp = (htp_connp_t*)handle_get(9, 0, false, nullptr);
    if (connp == nullptr) {
        connp = htp_connp_create(cfg);
        if (!connp) return;
        handle_register(9, connp);
        created_connp = true;
    }

    if (created_connp) {
        htp_time_t ts_open = {};
        ts_open.tv_sec = 1;
        htp_connp_open(connp, "127.0.0.1", 12345, "127.0.0.1", 80, &ts_open);

        static const char kReq[] = "GET / HTTP/1.1\r\nHost: a\r\n\r\n";
        htp_time_t ts_req = {};
        ts_req.tv_sec = 1;
        ts_req.tv_usec = 1000;
        (void)htp_connp_req_data(connp, &ts_req, kReq, sizeof(kReq) - 1);
        (void)htp_connp_req_data_consumed(connp);
        htp_connp_req_close(connp, &ts_req);

        static const char kRes[] = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
        htp_time_t ts_res = {};
        ts_res.tv_sec = 1;
        ts_res.tv_usec = 2000;
        (void)htp_connp_res_data(connp, &ts_res, kRes, sizeof(kRes) - 1);
        (void)htp_connp_res_data_consumed(connp);
    }

    if (handle_valid_count(17) == 0) {
        if (htp_tx_t* in_tx = htp_connp_get_in_tx(connp)) handle_register(17, in_tx);
        if (htp_tx_t* out_tx = htp_connp_get_out_tx(connp)) handle_register(17, out_tx);
        if (handle_valid_count(17) == 0) {
            if (htp_tx_t* tx = htp_connp_tx_create(connp)) handle_register(17, tx);
        }
    }
}

static void exercise_stateful_valid_flow() {
    htp_cfg_t* cfg = (htp_cfg_t*)handle_get(8, 0, false, nullptr);
    htp_connp_t* connp = (htp_connp_t*)handle_get(9, 0, false, nullptr);
    htp_tx_t* tx = (htp_tx_t*)handle_get(17, 0, false, nullptr);

    if (tx == nullptr && connp != nullptr) {
        tx = htp_connp_tx_create(connp);
        if (tx != nullptr) handle_register(17, tx);
    }

    {
        htp_base64_decoder decoder = {};
        htp_base64_decoder_init(&decoder);
        mark_api_direct_exec(78);  // htp_base64_decoder_init

        static const char kB64Input[] = "YWI=";
        uint8_t out[16] = {};
        (void)htp_base64_decode(&decoder, kB64Input, (int)(sizeof(kB64Input) - 1), out, (int)sizeof(out));
        mark_api_direct_exec(74);  // htp_base64_decode

        (void)htp_base64_decode_single('Q');
        mark_api_direct_exec(77);  // htp_base64_decode_single

        bstr* b64 = bstr_dup_c("YWI=");
        if (b64 != nullptr) {
            bstr* plain = htp_base64_decode_bstr(b64);
            mark_api_direct_exec(75);  // htp_base64_decode_bstr
            if (plain != nullptr) bstr_free(plain);
            bstr_free(b64);
        }

        bstr* plain2 = htp_base64_decode_mem("YWI=", 4);
        mark_api_direct_exec(76);  // htp_base64_decode_mem
        if (plain2 != nullptr) bstr_free(plain2);
    }

    {
        htp_list_array_t* list = htp_list_array_create(8);
        if (list != nullptr) {
            mark_api_direct_exec(173);  // htp_list_array_create
            int a = 1, b = 2, c = 3;
            (void)htp_list_array_push(list, &a);
            mark_api_direct_exec(178);  // htp_list_array_push
            (void)htp_list_array_push(list, &b);
            mark_api_direct_exec(178);  // htp_list_array_push
            (void)htp_list_array_get(list, 0);
            mark_api_direct_exec(175);  // htp_list_array_get
            (void)htp_list_array_size(list);
            mark_api_direct_exec(182);  // htp_list_array_size
            (void)htp_list_array_replace(list, 0, &c);
            mark_api_direct_exec(180);  // htp_list_array_replace
            (void)htp_list_array_pop(list);
            mark_api_direct_exec(177);  // htp_list_array_pop
            (void)htp_list_array_shift(list);
            mark_api_direct_exec(181);  // htp_list_array_shift
            htp_list_array_clear(list);
            mark_api_direct_exec(172);  // htp_list_array_clear
            htp_list_array_destroy(list);
            mark_api_direct_exec(174);  // htp_list_array_destroy
        }
    }

    {
        htp_table_t* table = htp_table_create(8);
        if (table != nullptr) {
            mark_api_direct_exec(195);  // htp_table_create
            int v = 7;
            bstr* k1 = bstr_dup_c("k1");
            bstr* k2 = bstr_dup_c("k2");
            bstr* k3 = bstr_dup_c("k3");
            if (k1 != nullptr) {
                (void)htp_table_add(table, k1, &v);
                mark_api_direct_exec(190);  // htp_table_add
                (void)htp_table_addk(table, k1, &v);
                mark_api_direct_exec(191);  // htp_table_addk
            }
            if (k2 != nullptr) {
                (void)htp_table_addn(table, k2, &v);
                mark_api_direct_exec(192);  // htp_table_addn
                // k2 ownership moved into table by addn
            }
            if (k1 != nullptr) {
                (void)htp_table_get(table, k1);
                mark_api_direct_exec(198);  // htp_table_get
            }
            (void)htp_table_get_c(table, "k1");
            mark_api_direct_exec(199);  // htp_table_get_c
            bstr* out_key = nullptr;
            (void)htp_table_get_index(table, 0, &out_key);
            mark_api_direct_exec(200);  // htp_table_get_index
            (void)htp_table_get_mem(table, "k1", 2);
            mark_api_direct_exec(201);  // htp_table_get_mem
            (void)htp_table_size(table);
            mark_api_direct_exec(202);  // htp_table_size
            htp_table_clear(table);
            mark_api_direct_exec(193);  // htp_table_clear
            htp_table_clear_ex(table);
            mark_api_direct_exec(194);  // htp_table_clear_ex
            htp_table_destroy(table);
            mark_api_direct_exec(196);  // htp_table_destroy
            if (k1 != nullptr) bstr_free(k1);  // addk key remains caller-owned
            if (k3 != nullptr) bstr_free(k3);
        }
        htp_table_t* table2 = htp_table_create(4);
        if (table2 != nullptr) {
            mark_api_direct_exec(195);  // htp_table_create
            htp_table_destroy_ex(table2);
            mark_api_direct_exec(197);  // htp_table_destroy_ex
        }
    }

    if (cfg != nullptr) {
        bstr* ct = bstr_dup_c("multipart/form-data; boundary=----proto");
        if (ct != nullptr) {
            bstr* found = nullptr;
            uint64_t flags = 0;
            (void)htp_mpartp_find_boundary(ct, &found, &flags);
            mark_api_direct_exec(187);  // htp_mpartp_find_boundary
            if (found != nullptr) bstr_free(found);
            bstr_free(ct);
        }

        bstr* boundary = bstr_dup_c("----proto");
        if (boundary != nullptr) {
            htp_mpartp_t* parser = htp_mpartp_create(cfg, boundary, 0);
            if (parser != nullptr) {
                mark_api_direct_exec(184);  // htp_mpartp_create
                static const char kMultipartBody[] =
                    "------proto\r\n"
                    "Content-Disposition: form-data; name=\"x\"\r\n\r\n"
                    "1\r\n"
                    "------proto--\r\n";
                (void)htp_mpartp_parse(parser, kMultipartBody, sizeof(kMultipartBody) - 1);
                mark_api_direct_exec(189);  // htp_mpartp_parse
                (void)htp_mpartp_get_multipart(parser);
                mark_api_direct_exec(188);  // htp_mpartp_get_multipart
                (void)htp_mpartp_finalize(parser);
                mark_api_direct_exec(186);  // htp_mpartp_finalize
                htp_mpartp_destroy(parser);
                mark_api_direct_exec(185);  // htp_mpartp_destroy
            } else {
                // Ownership transfer happens only on successful create.
                bstr_free(boundary);
            }
        }

        bstr* encoded = bstr_dup_c("a%2Bb%20c");
        if (encoded != nullptr) {
            uint64_t flags = 0;
            (void)htp_urldecode_inplace(cfg, HTP_DECODER_URLENCODED, encoded, &flags);
            mark_api_direct_exec(243);  // htp_urldecode_inplace
            int expected_status = 0;
            (void)htp_urldecode_inplace_ex(cfg, HTP_DECODER_URLENCODED, encoded, &flags, &expected_status);
            mark_api_direct_exec(244);  // htp_urldecode_inplace_ex
            bstr_free(encoded);
        }
    }

    if (tx != nullptr) {
        htp_urlenp_t* urlenp = htp_urlenp_create(tx);
        if (urlenp != nullptr) {
            mark_api_direct_exec(245);  // htp_urlenp_create
            static const char kP1[] = "a=1&";
            static const char kP2[] = "b=2";
            (void)htp_urlenp_parse_partial(urlenp, kP1, sizeof(kP1) - 1);
            mark_api_direct_exec(249);  // htp_urlenp_parse_partial
            (void)htp_urlenp_parse_complete(urlenp, kP2, sizeof(kP2) - 1);
            mark_api_direct_exec(248);  // htp_urlenp_parse_complete
            (void)htp_urlenp_finalize(urlenp);
            mark_api_direct_exec(247);  // htp_urlenp_finalize
            htp_urlenp_destroy(urlenp);
            mark_api_direct_exec(246);  // htp_urlenp_destroy
        }
    }

    if (connp != nullptr && tx != nullptr) {
        htp_decompressor_t* dec = htp_gzip_decompressor_create(connp, HTP_COMPRESSION_GZIP);
        if (dec != nullptr) {
            mark_api_direct_exec(163);  // htp_gzip_decompressor_create
            static const uint8_t kGzipData[] = {
                0x1f, 0x8b, 0x08, 0x00, 0, 0, 0, 0, 0, 0x03,
                0x03, 0x00, 0x00, 0x00, 0x00, 0x00
            };
            htp_tx_data_t td = {};
            td.tx = tx;
            td.data = kGzipData;
            td.len = sizeof(kGzipData);
            td.is_last = 1;
            (void)htp_gzip_decompressor_decompress(dec, &td);
            mark_api_direct_exec(164);  // htp_gzip_decompressor_decompress
            htp_gzip_decompressor_destroy(dec);
            mark_api_direct_exec(165);  // htp_gzip_decompressor_destroy
        }
    }
}

static void cleanup_valid_state_handles() {
    HandleTable& connp_tab = g_tables[9];
    for (uint32_t i = connp_tab.count; i >= 1; --i) {
        if (!connp_tab.valid[i] || connp_tab.handles[i] == nullptr) continue;
        auto* connp = (htp_connp_t*)connp_tab.handles[i];
        htp_time_t ts_close = {};
        ts_close.tv_sec = 2;
        htp_connp_req_close(connp, &ts_close);
        htp_connp_close(connp, &ts_close);
        htp_connp_destroy_all(connp);
        connp_tab.valid[i] = false;
        if (i == 1) break;
    }

    HandleTable& tx_tab = g_tables[17];
    for (uint32_t i = 1; i <= tx_tab.count; ++i) {
        tx_tab.valid[i] = false;
    }

    HandleTable& cfg_tab = g_tables[8];
    for (uint32_t i = cfg_tab.count; i >= 1; --i) {
        if (!cfg_tab.valid[i] || cfg_tab.handles[i] == nullptr) continue;
        auto* cfg = (htp_cfg_t*)cfg_tab.handles[i];
        htp_config_destroy(cfg);
        cfg_tab.valid[i] = false;
        if (i == 1) break;
    }
}

